1	/* ===== Phòng bầu trời chung: logic thuần, không phụ thuộc Cloudflare (Durable Object bọc ngoài) ===== */
2	import { multiParams as P } from '../../../src/explore/multi/params';
3	import { exSanitizeName } from '../../../src/explore/multi/protocol';
4	import type { ServerMsg, Flyer } from '../../../src/explore/multi/protocol';
5	import { exIsBad } from './badwords';
6	
7	export type Out = { to: string | 'all'; msg: ServerMsg };
8	
9	// pos: [slot, x, y, z, yaw, bank, giờ gửi]; giờ gửi = ts của khách (khách mới) hoặc giờ máy chủ nhận (khách cũ); dirty: có vị trí mới chưa phát
10	interface Slot { id: string; name: string; seen: number; pos: number[] | null; dirty: boolean }
11	interface Conn { stamps: number[] }
12	
13	const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
14	const wrapPi = (a: number) => a - Math.round(a / (2 * Math.PI)) * 2 * Math.PI;   // góc về [−π, π]
15	
16	export class SkyRoom {
17	  private conns = new Map<string, Conn>();
18	  private slots: (Slot | null)[] = new Array(P.slots).fill(null);
19	  private lastBroadcast = -Infinity;
20	
21	  private lobby(): Out {
22	    const flyers: Flyer[] = [];
23	    this.slots.forEach((s, i) => { if (s) flyers.push({ slot: i, name: s.name }); });
24	    return { to: 'all', msg: { t: 'lobby', flyers } };
25	  }
26	
27	  connect(id: string, now: number): Out[] | null {
28	    if (!this.conns.has(id) && this.conns.size >= P.maxConns) return null;
29	    this.conns.set(id, { stamps: [] });
30	    return [{ to: id, msg: this.lobby().msg }];
31	  }
32	
33	  slotOf(id: string): number { return this.slots.findIndex(s => s !== null && s.id === id); }
34	
35	  hasFlyers(): boolean { return this.slots.some(s => s !== null); }
36	
37	  /* Giờ có tin cuối của người giữ slot (để lưu vào attachment); -1 nếu không giữ slot */
38	  seenOf(id: string): number { const i = this.slotOf(id); return i < 0 ? -1 : this.slots[i].seen; }
39	
40	  /* Dựng lại sau hibernation. seen lấy từ attachment nếu có; không có (attachment cũ) thì coi như vừa im lặng gần hết hạn:
41	     người còn bay có một chu kỳ nhịp sống để lên tiếng, người đã chết không được gia hạn thêm mỗi lần thức dậy */
42	  restore(list: { id: string; slot: number; name: string; seen?: number }[], now: number): void {
43	    for (const e of list) {
44	      if (e.slot < 0 || e.slot >= P.slots) continue;
45	      if (!this.conns.has(e.id)) this.conns.set(e.id, { stamps: [] });
46	      const seen = typeof e.seen === 'number' && Number.isFinite(e.seen) ? Math.min(e.seen, now) : now - P.slotTimeoutMs + P.heartbeatMs;
47	      this.slots[e.slot] = { id: e.id, name: e.name, seen, pos: null, dirty: false };
48	    }
49	  }
50	
51	  message(id: string, raw: string, now: number): Out[] {
52	    const conn = this.conns.get(id);
53	    if (!conn || typeof raw !== 'string' || raw.length > P.maxMsgBytes) return [];
54	    let m: any;
55	    try { m = JSON.parse(raw); } catch { return []; }
56	    if (!m || typeof m !== 'object') return [];
57	    const slot = this.slotOf(id);
58	    switch (m.t) {
59	      case 'join': return this.onJoin(id, slot, m.name, now);
60	      case 'leave': return this.release(id) ? [this.lobby()] : [];
61	      case 'hb': if (slot < 0) return []; this.slots[slot].seen = now; return this.flush(now);
62	      case 'pos': return slot >= 0 ? this.onPos(conn, slot, m, now) : [];
63	      default: return [];
64	    }
65	  }
66	
67	  private onJoin(id: string, slot: number, rawName: unknown, now: number): Out[] {
68	    if (slot >= 0) return [];
69	    const name = typeof rawName === 'string' ? exSanitizeName(rawName) : null;
70	    if (name === null || exIsBad(name)) return [{ to: id, msg: { t: 'rejected', why: 'name' } }];
71	    const free = this.slots.findIndex(s => s === null);
72	    if (free < 0) return [{ to: id, msg: { t: 'rejected', why: 'full' } }];
73	    this.slots[free] = { id, name, seen: now, pos: null, dirty: false };
74	    return [{ to: id, msg: { t: 'joined', slot: free } }, this.lobby()];
75	  }
76	
77	  private onPos(conn: Conn, slot: number, m: any, now: number): Out[] {
78	    const { x, y, z, yaw, bank, ts } = m;
79	    for (const v of [x, y, z, yaw, bank]) if (typeof v !== 'number' || !Number.isFinite(v)) return [];
80	    conn.stamps = conn.stamps.filter(t => now - t < 1000);
81	    if (conn.stamps.length >= P.posMaxPerSec) return [];
82	    conn.stamps.push(now);
83	    const s = this.slots[slot]!;
84	    s.seen = now;
85	    s.pos = [slot, clamp(x, P.bounds.x0, P.bounds.x1), clamp(y, P.floor, P.ceiling), clamp(z, P.bounds.z0, P.bounds.z1), wrapPi(yaw), clamp(bank, -P.bankMax, P.bankMax), typeof ts === 'number' && Math.abs(ts) <= Number.MAX_SAFE_INTEGER ? ts : now];  // ts ngoài ±2^53 (kể cả NaN/∞) coi như không gửi, tránh đẩy độ lệch giờ của khách thành ∞
86	    s.dirty = true;
87	    return this.flush(now);
88	  }
89	
90	  /* Phát gói gộp các slot có vị trí mới (cách lần trước >= broadcastMs). Vị trí bị hãm trong cửa sổ vẫn dirty nên đi ở lần phát sau (pos hoặc hb của bất kỳ ai).
91	     Không phát lại vị trí cũ: khách cũ đóng dấu theo giờ nhận nên mẫu lặp làm dù đứng rồi vọt. Khách mới đặt mẫu theo e[6] */
92	  private flush(now: number): Out[] {
93	    if (now - this.lastBroadcast < P.broadcastMs) return [];
94	    const f: number[][] = [];
95	    for (const t of this.slots) if (t && t.dirty) { f.push(t.pos!); t.dirty = false; }
96	    if (!f.length) return [];
97	    this.lastBroadcast = now;
98	    return [{ to: 'all', msg: { t: 'pos', f } }];
99	  }
100	
101	  // Trả slot của kết nối; true nếu có slot được trả
102	  private release(id: string): boolean {
103	    const i = this.slotOf(id);
104	    if (i < 0) return false;
105	    this.slots[i] = null;
106	    return true;
107	  }
108	
109	  disconnect(id: string): Out[] {
110	    this.conns.delete(id);
111	    return this.release(id) ? [this.lobby()] : [];
112	  }
113	
114	  sweep(now: number): Out[] {
115	    const out: Out[] = [];
116	    this.slots.forEach((s, i) => {
117	      if (s && now - s.seen > P.slotTimeoutMs) { out.push({ to: s.id, msg: { t: 'released' } }); this.slots[i] = null; }
118	    });
119	    if (out.length) out.push(this.lobby());
120	    return out;
121	  }
122	}
