  const f = (o3[0].msg as any).f;
  assert.deepEqual(f.map((e: number[]) => e[0]), [0, 1]);
  assert.equal(f[0][1], 11); assert.equal(f[1][1], 20);
});

test('pos không slot / quá tốc độ / NaN bị bỏ; kẹp bounds và y', () => {
