  const e2 = (pos(r, 'a', { y: 99999, z: -99999, x: 0 }, 1200)[0].msg as any).f[0];
  assert.equal(e2[2], P.ceiling); assert.equal(e2[3], P.bounds.z0);
  // quá posMaxPerSec trong 1 s
  const r3 = new SkyRoom(); r3.connect('a', 0); join(r3, 'a', 'A');
